  "query": "select 'top_queries' as section, query, calls, total_exec_time, mean_exec_time, rows, shared_blks_read, shared_blks_hit from pg_stat_statements order by total_exec_time desc limit 20;

select 'activity' as section, pid, usename, state, wait_event_type, wait_event, now()-query_start as query_age, left(query,200) as query from pg_stat_activity where state <> 'idle' order by query_start nulls last;

select 'locks' as section, l.locktype, l.mode, l.granted, l.pid, left(a.query,160) as query from pg_locks l left join pg_stat_activity a using (pid) where not l.granted;

select 'tables' as section, schemaname, relname, n_live_tup, n_dead_tup, last_analyze, last_autoanalyze, last_vacuum, last_autovacuum, pg_size_pretty(pg_total_relation_size(relid)) as total_size from pg_stat_user_tables order by pg_total_relation_size(relid) desc limit 50;

select 'db' as section, datname, numbackends, xact_commit, xact_rollback, blks_read, blks_hit, tup_returned, tup_fetched from pg_stat_database where datname=current_database();"
}

